import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/files/upload-new-menu.png",n="/docs/images/files/upload-panel-failed.png",u=JSON.parse('{"title":"Upload files","description":"Upload any file to a workspace and see what each file type becomes.","frontmatter":{"title":"Upload files","description":"Upload any file to a workspace and see what each file type becomes.","type":"how-to"},"headers":[],"relativePath":"files/upload.md","filePath":"files/upload.md"}'),d={name:"files/upload.md"};function s(l,e,h,c,p,f){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="upload-files" tabindex="-1">Upload files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload files&quot;">​</a></h1><p>Upload files from your computer to a workspace, and each one becomes a document you can open, share, and organize.</p><p>Wafflebase picks the document type from the file extension. Spreadsheets, Word documents, and PowerPoint decks are converted so you can edit them. PDFs and images open in a viewer. Any other file is stored as-is so you can download it again.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be a member of the workspace.</li><li>Each file can be up to 100 MB. Image files are limited to 25 MB.</li><li>Uploads go into the folder you have open. To upload to the workspace root, go back to the top of the list first.</li></ul></div><h2 id="upload-from-the-new-menu" tabindex="-1">Upload from the New menu <a class="header-anchor" href="#upload-from-the-new-menu" aria-label="Permalink to &quot;Upload from the New menu&quot;">​</a></h2><ol><li>Open your workspace, or the folder you want the files in.</li><li>Click <strong>New</strong> in the top right.</li><li>Select <strong>Upload files…</strong>.</li><li>Choose one or more files and confirm.</li></ol><p>An <strong>Uploads</strong> panel opens in the bottom-right corner and shows each file&#39;s progress. When a file is done, its row shows an <strong>Open</strong> link.</p><p><img src="'+r+'" alt="New menu open with Upload files… and Import from Miro… below the create entries"></p><h3 id="drag-files-into-the-window" tabindex="-1">Drag files into the window <a class="header-anchor" href="#drag-files-into-the-window" aria-label="Permalink to &quot;Drag files into the window&quot;">​</a></h3><p>Drag files from your computer anywhere onto the documents list. The page shows <strong>Drop files to upload</strong>. Release to start the upload.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap <strong>New</strong>, then <strong>Upload files…</strong>. Your phone&#39;s file picker opens, so you can choose from files, photos, or other apps. Dragging files is not available on a phone.</p><h2 id="what-each-file-becomes" tabindex="-1">What each file becomes <a class="header-anchor" href="#what-each-file-becomes" aria-label="Permalink to &quot;What each file becomes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You upload</th><th>You get</th></tr></thead><tbody><tr><td><code>.xlsx</code></td><td>A <a href="/docs/sheets/">sheet</a>. Each worksheet becomes a tab.</td></tr><tr><td><code>.csv</code>, <code>.tsv</code></td><td>A sheet with one tab.</td></tr><tr><td><code>.json</code>, <code>.jsonl</code>, <code>.ndjson</code></td><td>A sheet with one tab. Object keys become a bold header row.</td></tr><tr><td><code>.parquet</code></td><td>A sheet with one tab.</td></tr><tr><td><code>.docx</code></td><td>A <a href="/docs/docs-editor/">doc</a>.</td></tr><tr><td><code>.pptx</code></td><td>A <a href="/docs/slides/">presentation</a>.</td></tr><tr><td><code>.pdf</code></td><td>A <a href="/docs/files/pdfs.html">PDF</a> you can read and comment on. The file is not converted.</td></tr><tr><td><code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.gif</code>, <code>.webp</code></td><td>An <a href="/docs/files/images.html">image</a> you can view and download.</td></tr><tr><td>Anything else</td><td>A stored file with no preview. You can download it again.</td></tr></tbody></table><p>A converted document is named after the file without its extension, so <code>budget.xlsx</code> becomes <strong>budget</strong>. A PDF, image, or other stored file keeps its full file name, such as <code>report.pdf</code>.</p><p>Uploading a Markdown (<code>.md</code>) file stores it as a file. It does not create a <a href="/docs/notes/">note</a>. To turn a Markdown file into a note, use <code>wafflebase notes import</code> in the <a href="/docs/developers/cli/documents.html#notes">command-line tool</a>.</p><p>For what each conversion keeps and the size and row limits, see <a href="/docs/files/import-export.html">Import and export</a>.</p><h2 id="track-and-retry-uploads" tabindex="-1">Track and retry uploads <a class="header-anchor" href="#track-and-retry-uploads" aria-label="Permalink to &quot;Track and retry uploads&quot;">​</a></h2><p>The <strong>Uploads</strong> panel lists every file in the current batch:</p><ul><li>A spinner shows a file that is still being read or uploaded.</li><li><strong>Open</strong> goes to a finished document.</li><li>An amber warning means the document was created with something left out, for example a large CSV that was cut short.</li><li>A red message means the upload failed. If a retry icon appears next to the file name, click it to try again.</li><li>The <strong>X</strong> at the end of a finished or failed row removes it from the panel.</li></ul><p>Click the arrow icon in the panel header to collapse the panel, or the <strong>X</strong> beside it (<strong>Clear finished uploads</strong>) to remove every finished row. Failed rows stay until you remove them.</p><p>You can open other documents while files upload; the panel stays in the corner. Keep the tab open until every file finishes, because closing or reloading the tab stops any upload that has not finished.</p><p><img src="'+n+'" alt="Uploads panel with one finished file showing Open and one failed file showing the 100 MB size-limit message"></p><h3 id="fix-a-failed-upload" tabindex="-1">Fix a failed upload <a class="header-anchor" href="#fix-a-failed-upload" aria-label="Permalink to &quot;Fix a failed upload&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>What to do</th></tr></thead><tbody><tr><td><code>File is larger than the 100 MB limit</code> (or <code>25 MB</code> for an image)</td><td>Make the file smaller, or split it, and upload it again.</td></tr><tr><td><code>Couldn&#39;t upload this file. Check your connection and retry.</code></td><td>Check your connection, then click the retry icon.</td></tr><tr><td><code>Couldn&#39;t load the importer. Reload the page, then retry.</code></td><td>Reload the page, then upload the file again.</td></tr><tr><td><code>This file has too many columns to import</code></td><td>The first row of the CSV or TSV is too wide. Split the columns into several files.</td></tr><tr><td><code>This file does not contain any data.</code></td><td>The CSV or TSV file is empty. Check the file and upload it again.</td></tr></tbody></table><h2 id="import-a-miro-board" tabindex="-1">Import a Miro board <a class="header-anchor" href="#import-a-miro-board" aria-label="Permalink to &quot;Import a Miro board&quot;">​</a></h2><ol><li>Open your workspace or folder. The entry is not shown on the list of all documents across workspaces.</li><li>Click <strong>New</strong> and select <strong>Import from Miro…</strong>.</li><li>Paste your Miro <strong>Access token</strong> and the <strong>Board URL</strong>.</li><li>Click <strong>Import</strong>.</li></ol><p>The import continues in the background and shows its progress in the <strong>Uploads</strong> panel. A failed Miro import has no retry icon; start the import again from the <strong>New</strong> menu. When it finishes, the board appears in your list. The access token is used only for this import and is not stored. For what comes across from Miro, see <a href="/docs/board/export-and-import.html">Board export and import</a>.</p><h2 id="open-a-file-with-no-preview" tabindex="-1">Open a file with no preview <a class="header-anchor" href="#open-a-file-with-no-preview" aria-label="Permalink to &quot;Open a file with no preview&quot;">​</a></h2><p>A file that is not a sheet, doc, presentation, PDF, or image opens as a card with its file type, size, and upload date, and the note <strong>No preview available</strong>.</p><ol><li>Open the file from the documents list.</li><li>Click the download icon (<strong>Download file</strong>) in the header.</li></ol><p>The original file downloads to your computer. You can rename the file by clicking its title in the header, and <a href="/docs/collaborate/share.html">share it</a> like any other document.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Every upload creates a new document. To update an uploaded PDF, image, or file, upload the new version and move the old one to the <a href="/docs/collaborate/trash.html">trash</a>.</li><li>Self-hosted deployments need file storage configured before uploads work. See <a href="/docs/developers/self-hosting/configuration.html">Configuration</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/files/import-export.html">Import and export</a> for the formats, limits, and what each conversion keeps.</li><li><a href="/docs/files/pdfs.html">Read and comment on PDFs</a> after you upload one.</li><li><a href="/docs/collaborate/folders.html">Folders</a> to organize what you uploaded.</li><li><a href="/docs/developers/cli/files-and-images.html">Files and images on the CLI</a> to upload from a script.</li></ul>',36)])])}const g=o(d,[["render",s]]);export{u as __pageData,g as default};
